// Overview, payments, support inbox, suggestions, user reports, reports, call setup, and the staff portals
// (property owner, agency, agent, support). Every number comes from the live database.
import { friendlyErr } from "./ui.js";
import * as st from "./store.js";
import * as CALLS from "./calls.js";
import * as VS from "./viewsafe.js";
import { pickLocation } from "./maps.js";
import * as AX from "./ax.js";
import { createList } from "./ax-list.js";
import { listingState, isPendingL, roleOf, emailPending } from "./admin2.js";
import { locFields, mountLoc, listingLoc, listingLocError } from "./loc.js";
import { storage } from "./firebase.js";
import { ref as storageRef, uploadBytes, deleteObject } from "https://www.gstatic.com/firebasejs/10.14.1/firebase-storage.js";

const { $, $$, esc, I, btn, chipFor, chip, avatar, thumb, fmt, toast, dialog, confirm, menu, drawer, data, empty, tabs, mountTabs, dl, section, timeline, setQ, hq, changed, csv, pageView, pageHead, kpi, mini, attn, spark, areaChart, barChart, donut, rank, progress, pctDelta, mountCharts, animateCounts, bulkRun, ms, staffFlags } = AX;
const fe = (e) => friendlyErr(e).replace(/\s*\([^)]*\)\s*$/, "");
const bad = (e) => toast(fe(e), { tone: "bad" });
const busy = (b, on) => { if (!b) return; b.classList.toggle("is-busy", on); b.disabled = on; };
const naira = fmt.naira, DAY = 864e5;
const meName = (ctx) => ctx.S.profile?.name || ctx.S.user.displayName || ctx.S.user.email || "Admin";
const isRes = (t) => /resolved|closed/i.test(t.status || "");
const isActive = (l) => l.status === "active" && !l.archived;
const sosOpen = (v) => !!(v.sos && !v.sos.resolved);
const rentOf = (a) => +a.rent || +a.amount || 0;
const approved = (a) => /approved|active/i.test(a.status || "");
const thumbOf = (l) => l.thumb || l.images?.[0] || "";
export const allowed = (ctx, kind) => ctx.S.isAdmin || ctx.S.role === kind;
export const denied = (ctx) => ({ title: "Not available", ...(ctx.S.isAdmin || ["landlord", "agency", "agent", "support"].includes(ctx.S.role) ? staffFlags(ctx) : {}), html: `<div class="ax-card" style="margin-top:8px">${empty({ icon: "lock", title: "This area is not available for your account.", hint: "Ask the Faxton owner to give your account access.", action: btn("Back home", { href: "#/" }) })}</div>` });

// ---------- time buckets ----------
const PERIODS = [["7", "Last 7 days"], ["30", "Last 30 days"], ["90", "Last 90 days"], ["365", "Last 12 months"]];
function buckets(p) {
  const d0 = new Date(); d0.setHours(0, 0, 0, 0); const out = [], lab = (d) => d.toLocaleDateString("en-GB", { day: "numeric", month: "short" });
  if (p === "365") { for (let i = 11; i >= 0; i--) { const s = new Date(d0.getFullYear(), d0.getMonth() - i, 1), e = new Date(d0.getFullYear(), d0.getMonth() - i + 1, 1); out.push({ start: +s, end: +e, label: s.toLocaleDateString("en-GB", { month: "short" }), full: s.toLocaleDateString("en-GB", { month: "long", year: "numeric" }) }); } return out; }
  if (p === "90") { for (let i = 12; i >= 0; i--) { const e = +d0 + DAY - i * 7 * DAY, s = e - 7 * DAY; out.push({ start: s, end: e, label: lab(new Date(s)), full: "Week of " + lab(new Date(s)) }); } return out; }
  for (let i = +p - 1; i >= 0; i--) { const s = +d0 - i * DAY; out.push({ start: s, end: s + DAY, label: lab(new Date(s)), full: new Date(s).toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short" }) }); } return out;
}
const per = (docs, bs, pick = (d) => ms(d.createdAt)) => bs.map((b) => docs.filter((d) => { const t = pick(d); return t >= b.start && t < b.end; }).length);
const cum = (docs, bs, pick = (d) => ms(d.createdAt)) => bs.map((b) => docs.filter((d) => { const t = pick(d); return t && t < b.end; }).length);
const within = (docs, a, b, pick = (d) => ms(d.createdAt)) => docs.filter((d) => { const t = pick(d); return t >= a && t < b; }).length;
let period = "30"; try { period = sessionStorage.getItem("axPeriod") || "30"; } catch {}
const months6 = () => { const d0 = new Date(), a = []; for (let i = 5; i >= 0; i--) { const s = new Date(d0.getFullYear(), d0.getMonth() - i, 1); a.push({ start: +s, end: +new Date(s.getFullYear(), s.getMonth() + 1, 1), full: s.toLocaleDateString("en-GB", { month: "long", year: "numeric" }) }); } return a; };
const card = (title, sub, inner, { right = "", cls = "", tag = "", pad = true } = {}) => `<section class="ax-card ${cls}" ${tag ? `data-t="${tag}"` : ""}><header><div><h2>${esc(title)}</h2>${sub ? `<p>${esc(sub)}</p>` : ""}</div>${right}</header><div class="${pad ? "ax-cb" : ""}">${inner}</div></section>`;
const miniTable = (head, rows, emptyHtml) => (rows.length ? `<div class="ax-scroll"><table class="ax-table ax-sm-table"><thead><tr>${head.map(([h, a]) => `<th class="${a || ""}">${esc(h)}</th>`).join("")}</tr></thead><tbody>${rows.join("")}</tbody></table></div>` : emptyHtml);

// ---------- overview (owner and admin) ----------
export function overview(ctx) {
  const hello = (() => { const h = new Date().getHours(), n = AX.first(ctx.S.profile?.name || ctx.S.user.displayName); return `${h < 12 ? "Good morning" : h < 17 ? "Good afternoon" : "Good evening"}${n ? ", " + n : ""}`; })();
  return { ...pageView(ctx, { title: "Overview", head: false, kpis: true, cols: ["listings", "applications", "viewings", "users", "tickets"], what: "the overview",
    async render({ listings: ls, applications: ap, viewings: vw, users: us, tickets: tk }) {
      const date = new Date().toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short", year: "numeric" });
      const canSeed = ctx.S.isOwner && !ls.length && st.demoMode();
      const head = `<header class="ax-ph"><div class="ax-ph-t"><span class="ax-eyebrow">Overview · ${esc(date)}</span><h1>${esc(hello)}</h1><p class="ax-sub">Here is what needs you today.</p></div><div class="ax-ph-a"><label class="ax-sr" for="ovp">Period</label><select class="ax-input" id="ovp" style="width:auto">${PERIODS.map(([v, l]) => `<option value="${v}" ${v === period ? "selected" : ""}>${l}</option>`).join("")}</select>${btn("Export report", { ic: "download", attrs: "data-act=export" })}${canSeed ? btn("Add demo listings (sample data)", { attrs: "data-act=seed" }) : ""}<button type="button" class="ax-ib ax-refresh" data-ax="refresh" aria-label="Refresh">${I("refresh", 18)}</button></div></header>`;
      const build = () => {
        const bs = buckets(period), a = bs[0].start, b = bs[bs.length - 1].end, pa = a - (b - a), n = period === "365" ? "12 months" : period + " days", vs = "vs previous " + n;
        const uS = per(us, bs), lS = per(ls, bs), aS = per(ap, bs), vS = per(vw, bs), tS = per(tk, bs), sU = within(us, a, b), pU = within(us, pa, a), sL = within(ls, a, b), pL = within(ls, pa, a), sA = within(ap, a, b), pA = within(ap, pa, a), sV = within(vw, a, b), pV = within(vw, pa, a), sT = within(tk, a, b);
        const active = ls.filter(isActive), pending = ls.filter(isPendingL), toRev = ap.filter((x) => /review/i.test(x.status || "")), ten = ap.filter(approved), vol = ten.reduce((s, x) => s + rentOf(x), 0);
        const pendV = us.filter((u) => u.verification?.status === "pending").length + us.filter((u) => u.deletion?.status === "pending").length;
        const pendE = us.filter(emailPending).length;
        const attns = [attn({ label: "Safety alerts", count: vw.filter(sosOpen).length, href: "/admin/viewings?tab=safety", alert: true, icon: "alert" }), attn({ label: "Listings awaiting approval", count: pending.length, href: "/admin/listings?tab=pending", icon: "clipList" }), attn({ label: "Verifications and deletions", count: pendV, href: "/admin/verifications", icon: "shield" }), attn({ label: "Applications to review", count: toRev.length, href: "/admin/applications?tab=Under review", icon: "doc" }), attn({ label: "Viewing requests", count: vw.filter((v) => v.status === "Requested").length, href: "/admin/viewings?tab=Requested", icon: "calDots" }), attn({ label: "Open tickets", count: tk.filter((t) => !isRes(t)).length, href: "/admin/support", icon: "chatdots" }), attn({ label: "Accounts pending email verification", count: pendE, href: "/admin/users?tab=pending", icon: "mail" })].join("");
        const roles = {}; us.forEach((u) => { const r = roleOf(ctx, u), k = { owner: "Owner", admin: "Admin", agent: "Agent", landlord: "Property owner", agency: "Agency", support: "Support" }[r] || "Renter"; roles[k] = (roles[k] || 0) + 1; });
        const byCity = {}; active.forEach((l) => { const c = l.city || "Other"; byCity[c] = (byCity[c] || 0) + 1; });
        const types = {}; active.forEach((l) => { const t = l.type || "Other"; (types[t] ||= []).push(+l.price || 0); });
        const old = [...pending].sort((x, y) => ms(x.createdAt) - ms(y.createdAt)).slice(0, 5);
        const feed = [...ap.map((x) => ({ t: ms(x.createdAt), ic: "doc", a: `${x.name || "Someone"} applied for ${x.title || "a home"}`, s: x.status, h: "/admin/applications?id=" + x.id })), ...vw.map((x) => ({ t: ms(x.createdAt), ic: sosOpen(x) ? "alert" : "calDots", a: sosOpen(x) ? `Safety alert at ${x.title || "a viewing"}` : `${x.name || "Someone"} booked a viewing at ${x.title || "a home"}`, s: x.status, h: "/admin/viewings?id=" + x.id })), ...tk.map((x) => ({ t: ms(x.createdAt), ic: "chatdots", a: `${x.name || "Someone"} opened a ticket: ${x.subject || ""}`, s: x.status, h: "/admin/support?id=" + x.id })), ...us.filter((u) => u.verification?.requestedAt).map((u) => ({ t: u.verification.requestedAt, ic: "shield", a: `${u.name || "Someone"} asked to be verified`, s: u.verification.status, h: "/admin/verifications" }))].filter((e) => e.t).sort((x, y) => y.t - x.t).slice(0, 7);
        const m6 = months6();
        return `<div class="ax-attns" data-t="att">${attns}</div>
        <div class="ax-kpis scroll" data-t="kpis">${kpi({ label: "Total users", value: fmt.num(us.length), count: us.length, d: pctDelta(sU, pU), vs, sub: pendE ? `${pendE} pending email verification` : "", icon: "users", href: "/admin/users", sp: spark(uS) })}${kpi({ label: "Active listings", value: fmt.num(active.length), count: active.length, d: pctDelta(sL, pL), vs, sub: `${pending.length} awaiting approval`, icon: "home", href: "/admin/listings", sp: spark(lS) })}${kpi({ label: "Applications", value: fmt.num(sA), count: sA, d: pctDelta(sA, pA), vs, sub: `${toRev.length} to review`, icon: "doc", href: "/admin/applications", sp: spark(aS) })}${kpi({ label: "Approved rent volume", value: fmt.nairaC(vol), title: vol ? naira(vol) : "", sub: `${ten.length} tenanc${ten.length === 1 ? "y" : "ies"}`, icon: "wallet", href: "/admin/payments", sp: spark(per(ten, bs)) })}</div>
        <div class="ax-minis scroll">${mini({ label: "New signups", value: fmt.num(sU), icon: "user", href: "/admin/users" })}${mini({ label: "Listing growth", value: "+" + sL, sub: "new listings", icon: "trend", href: "/admin/listings" })}${mini({ label: "Viewings", value: fmt.num(sV), icon: "calDots", href: "/admin/viewings" })}${mini({ label: "Tickets received", value: fmt.num(sT), icon: "chatdots", href: "/admin/support" })}</div>
        <div class="ax-grid"><div class="ax-c8" data-t="chart">${card("Applications and viewings", PERIODS.find((p) => p[0] === period)[1], barChart([{ name: "Applications", data: aS }, { name: "Viewings", data: vS }], bs.map((x) => x.label)))}</div><div class="ax-c4 ax-rs2">${card("Recent activity", "", feed.length ? `<ul class="ax-feed">${feed.map((e) => `<li><a href="#${esc(e.h)}"><span class="ax-tile">${I(e.ic, 16)}</span><div><b>${esc(e.a)}</b><small>${esc(e.s || "")}</small></div><time>${fmt.rel(e.t)}</time></a></li>`).join("")}</ul>` : empty({ icon: "clock", title: "No activity yet", hint: "New applications, viewings and tickets show up here." }), { pad: false })}</div>
        <div class="ax-c8">${card("Pending approvals", "Oldest first", miniTable([["Property"], ["Agent"], ["Submitted"], ["", "al-right"]], old.map((l) => `<tr><td data-label="Property"><div class="ax-id">${thumb(thumbOf(l), 32)}<div><b>${esc(l.title)}</b><small>${esc([l.area, l.city].filter(Boolean).join(", "))}</small></div></div></td><td data-label="Agent">${esc(l.agent?.name || "—")}</td><td data-label="Submitted">${fmt.rel(l.createdAt)}</td><td class="al-right"><div class="ax-ra" style="justify-content:flex-end">${btn("Approve", { v: "soft", size: "sm", attrs: `data-ap="${esc(l.id)}"` })}${btn("Review", { v: "ghost", size: "sm", href: "#/admin/listings?id=" + encodeURIComponent(l.id) })}</div></td></tr>`), empty({ icon: "checkc", title: "Nothing waiting for approval", hint: "New listings from agents appear here." })), { right: `<a class="ax-link" href="#/admin/listings?tab=pending">View all</a>`, pad: false, tag: "queue" })}</div></div>
        <div class="ax-grid ax-lazy"><div class="ax-c4">${card("Users by role", "Everyone on the platform", donut(Object.entries(roles).sort((x, y) => y[1] - x[1]), { value: us.length, label: "Total users" }))}</div><div class="ax-c4">${card("New signups", "People who joined", barChart([{ name: "Signups", data: uS }], bs.map((x) => x.label), { h: 180 }))}</div><div class="ax-c4">${card("Listings growth", "All listings on the platform", areaChart([{ name: "Listings", data: cum(ls, bs) }], bs.map((x) => x.label), { h: 180 }))}</div></div>
        <div class="ax-grid ax-lazy"><div class="ax-c8">${card("Monthly platform metrics", "The last six months", miniTable([["Month"], ["New users", "al-right"], ["New listings", "al-right"], ["Applications", "al-right"], ["Viewings", "al-right"], ["Tickets", "al-right"]], [...m6].reverse().map((m) => `<tr><td data-label="Month"><b>${m.full}</b></td>${[us, ls, ap, vw, tk].map((d, i) => `<td class="al-right num" data-label="${["New users", "New listings", "Applications", "Viewings", "Tickets"][i]}">${within(d, m.start, m.end)}</td>`).join("")}</tr>`), ""), { pad: false })}</div><div class="ax-c4 ax-stack">${card("Listings by city", "Active listings", rank(Object.entries(byCity).sort((x, y) => y[1] - x[1]).slice(0, 6).map(([c, v]) => ({ label: c, value: v, href: "/admin/listings?city=" + encodeURIComponent(c) + "&tab=active" }))))}${card("Property categories", "Active listings and average rent", miniTable([["Category"], ["Listings", "al-right"], ["Avg rent", "al-right"]], Object.entries(types).sort((x, y) => y[1].length - x[1].length).map(([t, p]) => `<tr><td data-label="Category"><b>${esc(t)}</b></td><td class="al-right num" data-label="Listings">${p.length}</td><td class="al-right num" data-label="Avg rent">${naira(Math.round(p.reduce((s, x) => s + x, 0) / p.length))}</td></tr>`), empty({ icon: "home", title: "No active listings yet" })), { pad: false })}</div></div>`;
      };
      return { html: `${head}<div id="ovBody">${build()}</div>`, mount(el) {
        const host = $("#ovBody", el);
        const paint = () => { host.innerHTML = build(); mountCharts(host); animateCounts(host); bindPending(host); };
        const bindPending = (h) => $("[data-ap]", h).forEach((b) => (b.onclick = async () => { const l = ls.find((x) => x.id === b.dataset.ap); const ownerRows = await data.safe("users"), owner = ownerRows.find((u) => u.id === l?.ownerUid); if (l?.ownerUid && (!owner || !(owner.verified === true || owner.verification?.status === "verified"))) return toast("This listing needs a verified owner before approval.", { tone: "bad" }); if (owner?.role === "landlord") return toast("Open Marketplace → Listings to review this property’s private ownership proof before approving it."); busy(b, true); try { await st.patch("listings", l.id, { status: "active", archived: false }); Object.assign(l, { status: "active", archived: false }); changed(); st.notify(l.ownerUid, { kind: "info", title: "Your listing is live", body: `${l.title} has been approved.` }).catch(() => {}); paint(); toast("Listing approved.", { action: "Undo", onAction: async () => { try { await st.patch("listings", l.id, { status: "pending", archived: false }); Object.assign(l, { status: "pending" }); changed(); paint(); } catch (e) { bad(e); } } }); } catch (e) { busy(b, false); bad(e); } }));
        bindPending(host);
        $("#ovp", el).onchange = (e) => { period = e.target.value; try { sessionStorage.setItem("axPeriod", period); } catch {} paint(); };
        $("[data-act=export]", el).onclick = () => { const m = months6(); csv("faxton-platform-report", ["Month", "New users", "New listings", "Applications", "Viewings", "Tickets"], m.map((x) => [x.full, within(us, x.start, x.end), within(ls, x.start, x.end), within(ap, x.start, x.end), within(vw, x.start, x.end), within(tk, x.start, x.end)])); };
        const seed = $("[data-act=seed]", el); if (seed) seed.onclick = async () => { if (!(await confirm({ title: "Add demo listings?", body: "This adds made-up sample homes (fake agents and prices) so you can see how the site looks. Visitors will see them too. Delete them all before you launch.", confirmLabel: "Add demo data" }))) return; busy(seed, true); try { await st.seedListings(); data.invalidate("listings"); toast("Demo listings added. Remember to delete them before launch."); ctx.render(); } catch (e) { busy(seed, false); bad(e); } };
      } };
    } }) };
}

// ---------- payments ----------
export function payments(ctx) {
  return pageView(ctx, { title: "Payments", eyebrow: "Activity", sub: "Amounts due on move-in and the transfers tenants say they have made.", cols: ["applications", ["proofs", () => data.safe("paymentProofs")]], what: "payments",
    async render({ applications: ap, proofs }) {
      const sum = (l) => l.reduce((s, a) => s + (+a.amount || 0), 0), paid = ap.filter(approved), open = ap.filter((a) => /review|awaiting/i.test(a.status || "")), rej = ap.filter((a) => /reject/i.test(a.status || ""));
      const grp = (a) => (approved(a) ? "approved" : /reject/i.test(a.status || "") ? "rejected" : "awaiting");
      return { html: `<div class="ax-banner">${I("info", 20)}<div><b>Online payment is not switched on yet.</b><p>These are the amounts due, not money received. Tenants can pay by bank transfer and send proof below.</p></div></div>
        <div class="ax-minis">${mini({ label: "Approved, due on move-in", value: naira(sum(paid)), sub: `${paid.length} application${paid.length === 1 ? "" : "s"}`, icon: "wallet" })}${mini({ label: "Awaiting a decision", value: naira(sum(open)), sub: `${open.length} application${open.length === 1 ? "" : "s"}`, icon: "clock" })}${mini({ label: "All applications", value: naira(sum(ap)), sub: `${ap.length} in total`, icon: "doc" })}${mini({ label: "Transfers to confirm", value: fmt.num(proofs.filter((p) => /submitted/i.test(p.status || "")).length), sub: `${proofs.length} proof${proofs.length === 1 ? "" : "s"} sent`, icon: "receipt" })}</div>
        <div id="payList" style="margin-top:16px"></div>
        <h2 class="ax-sec-h" style="margin:28px 0 12px;font:600 15px var(--font-display);color:var(--ax-head)">Tenant payment proofs</h2><div id="proofs" class="ax-card ax-tablecard"></div>
        <h2 style="margin:28px 0 12px;font:600 15px var(--font-display);color:var(--ax-head)">Bank transfer details</h2><div id="payHost" class="ax-card" style="padding:20px"><div class="ax-skel" style="height:80px"></div></div>`, mount(el) {
        createList($("#payList", el), { noun: "payments", label: "Payments", rows: ap, placeholder: "Search applicant or property…",
          tabs: [{ k: "all", label: "All" }, { k: "approved", label: "Approved", test: (a) => grp(a) === "approved" }, { k: "awaiting", label: "Awaiting", test: (a) => grp(a) === "awaiting" }, { k: "rejected", label: "Rejected", test: (a) => grp(a) === "rejected" }], sort: { k: "created", dir: "desc" },
          search: (a) => `${a.name || ""} ${a.title || ""} ${a.email || ""}`,
          cols: [{ k: "who", label: "Applicant", role: "title", sort: (a) => String(a.name || "").toLowerCase(), cell: (a) => `<div class="ax-id">${avatar(a.name, a.uid, 32)}<div><b>${esc(a.name || "Applicant")}</b><small>${esc(a.email || "")}</small></div></div>` }, { k: "prop", label: "Property", pri: 2, cell: (a) => esc(a.title || "—") }, { k: "amount", label: "Amount", align: "right", sort: (a) => +a.amount || 0, cell: (a) => `<span class="ax-money">${naira(a.amount)}</span>` }, { k: "status", label: "Status", role: "status", cell: (a) => chipFor("application", a.status || "Under review") }, { k: "created", label: "Submitted", pri: 2, sort: (a) => ms(a.createdAt), cell: (a) => fmt.rel(a.createdAt) }],
          csv: { name: "faxton-payments", head: ["Applicant", "Property", "Amount", "Status", "Submitted"], row: (a) => [a.name, a.title, a.amount, a.status, fmt.date(a.createdAt)] },
          drawer: (a) => ({ title: a.name || "Application", sub: chipFor("application", a.status || "Under review"), body: `${section("Move-in amount", dl([["Yearly rent", naira(a.rent)], ["Move-in total", `<b>${naira(a.amount)}</b>`], ["Property", esc(a.title)], ["Move-in date", a.moveIn ? esc(fmt.date(a.moveIn)) : ""]]))}<p class="ax-help">Online payment is not switched on, so this is the amount due, not money received.</p>`, footer: btn("Open application", { href: "#/admin/applications?id=" + encodeURIComponent(a.id) }) }),
          empty: { icon: "wallet", title: "No applications yet, so there is nothing to collect.", hint: "Approved applications show their move-in amount here." } });
        proofTable($("#proofs", el), proofs, ctx);
        import("./paymentinfo.js").then((m) => { const host = $("#payHost", el); host.innerHTML = ""; if (!host.isConnected) return; return m.mountPaymentSettings(host, ctx); }).catch(() => { const h = $("#payHost", el); if (h) h.innerHTML = `<p class="ax-muted">Bank transfer settings will appear here soon.</p>`; });
      } };
    } });
}
function proofTable(host, proofs, ctx) {
  const sorted = [...proofs].sort((a, b) => ms(b.createdAt) - ms(a.createdAt)), paint = () => {
    host.innerHTML = sorted.length ? `<div class="ax-scroll"><table class="ax-table" aria-label="Payment proofs"><thead><tr><th>Tenant</th><th>Property</th><th class="al-right">Amount</th><th>Reference</th><th>Proof</th><th>Status</th><th class="al-right">Decision</th></tr></thead><tbody>${sorted.map((p) => `<tr data-id="${esc(p.id)}"><td data-role="title" data-label="Tenant"><div class="ax-id">${avatar(p.name, p.uid, 28)}<div><b>${esc(p.name || "Tenant")}</b><small>${fmt.rel(p.createdAt)}</small></div></div></td><td data-label="Property">${esc(p.title || "—")}</td><td class="al-right" data-label="Amount"><span class="ax-money">${naira(p.amount)}</span></td><td data-label="Reference" class="num">${esc(p.reference || "—")}</td><td data-label="Proof">${p.proof ? `<button type="button" class="ax-link" data-proof="${esc(p.id)}" style="border:0;background:none;cursor:pointer;padding:0">View</button>` : "—"}</td><td data-role="status" data-label="Status">${chipFor("proof", p.status || "Submitted")}</td><td data-role="actions" class="al-right"><div class="ax-ra" style="justify-content:flex-end">${/submitted/i.test(p.status || "Submitted") ? `${btn("Approve", { v: "soft", size: "sm", attrs: `data-pd=Confirmed data-id="${esc(p.id)}"` })}${btn("Reject", { v: "danger", size: "sm", attrs: `data-pd=Rejected data-id="${esc(p.id)}"` })}` : ""}</div></td></tr>`).join("")}</tbody></table></div>` : empty({ icon: "receipt", title: "No payment proofs yet", hint: "When a tenant sends proof of a bank transfer, it appears here for you to confirm." });
  };
  paint();
  host.onclick = async (e) => {
    const v = e.target.closest("[data-proof]"), d = e.target.closest("[data-pd]");
    if (v) { const p = proofs.find((x) => x.id === v.dataset.proof); dialog({ title: "Proof of payment", size: "md", icon: "receipt", body: `${/^data:image\//.test(p.proof) ? `<img class="ax-proof" src="${esc(p.proof)}" alt="Proof of payment">` : `<a class="ax-ext" href="${esc(p.proof)}" download="proof">Download the file</a>`}${p.note ? `<p class="ax-p" style="margin-top:12px">${esc(p.note)}</p>` : ""}` }); }
    else if (d) { const p = proofs.find((x) => x.id === d.dataset.id), ok = d.dataset.pd === "Confirmed"; busy(d, true);
      try { await st.patch("paymentProofs", p.id, { status: d.dataset.pd, decidedAt: Date.now(), decidedBy: ctx.S.user.uid }); p.status = d.dataset.pd; changed(); st.notify(p.uid, { kind: ok ? "verified" : "rejected", title: ok ? "Payment confirmed" : "Payment not confirmed", body: ok ? `We confirmed your transfer for ${p.title || "your rental"}.` : `We couldn’t match your transfer for ${p.title || "your rental"}. Please check the details and send it again.` }).catch(() => {}); toast(ok ? "Payment confirmed." : "Payment rejected."); paint(); } catch (x) { busy(d, false); bad(x); } }
  };
}

// ---------- support inbox ----------
const groupOf = (t) => (isRes(t) ? "Resolved" : /progress/i.test(t.status || "") ? "In progress" : "Open");

// ---------- suggestions ----------
const SG = ["New", "Reviewed", "Planned", "Done"];
export function suggestions(ctx) {
  return pageView(ctx, { title: "Suggestions", eyebrow: ctx.S.isAdmin ? "Support" : "Support console", sub: "Ideas and feedback sent from the Contact us page.", cols: ["suggestions"], what: "suggestions",
    async render({ suggestions: items }) {
      const stOf = (x) => x.status || "New", set = async (x, s, api) => { const prev = stOf(x); try { await st.patch("suggestions", x.id, { status: s }); x.status = s; changed(); api.refresh(); toast(`Marked ${s.toLowerCase()}.`, { action: "Undo", onAction: async () => { try { await st.patch("suggestions", x.id, { status: prev }); x.status = prev; changed(); api.refresh(); } catch (e) { bad(e); } } }); } catch (e) { bad(e); } };
      return { html: `<div id="sg"></div>`, mount(el) {
        createList($("#sg", el), { noun: "suggestions", label: "Suggestions", rows: items, placeholder: "Search suggestions…", tabs: [{ k: "all", label: "All" }, ...SG.map((s) => ({ k: s, label: s, test: (x) => stOf(x) === s }))], sort: { k: "date", dir: "desc" }, search: (x) => `${x.name || ""} ${x.email || ""} ${x.topic || ""} ${x.text || ""}`,
          cols: [{ k: "from", label: "From", role: "title", cell: (x) => `<div class="ax-id">${avatar(x.name, x.uid, 32)}<div><b>${esc(x.name || "—")}</b><small>${esc(x.email || "")}</small></div></div>` }, { k: "topic", label: "Topic", pri: 2, cell: (x) => esc(x.topic || "General") }, { k: "text", label: "Suggestion", cell: (x) => `<div class="ax-clamp" style="-webkit-line-clamp:2;max-width:380px">${esc(x.text || "")}</div>` }, { k: "date", label: "Date", pri: 2, sort: (x) => ms(x.createdAt), cell: (x) => fmt.date(x.createdAt) }, { k: "status", label: "Status", role: "status", cell: (x) => `<button type="button" class="ax-chipbtn" data-cell="s" aria-haspopup="menu" aria-label="Change status, now ${esc(stOf(x))}">${chipFor("suggestion", stOf(x))}${I("chevD", 14)}</button>` }],
          onCell: (k, x, b, api) => menu(b, SG.map((s) => ({ label: s, checked: s === stOf(x), act: () => s !== stOf(x) && set(x, s, api) })), { align: "left", label: "Status" }),
          bulk: [{ label: "Set status", icon: "refresh", run: (rs, c) => menu($("[data-bulk=0]"), SG.map((s) => ({ label: s, act: async () => { const prev = new Map(rs.map((x) => [x.id, stOf(x)])); const r = await bulkRun(rs.map((x) => x.id), async (id) => { const x = rs.find((y) => y.id === id); await st.patch("suggestions", id, { status: s }); x.status = s; }, { label: "Updating" }); changed(); c.clear(); toast(`${r.ok.length} marked ${s.toLowerCase()}.`, { action: "Undo", onAction: async () => { await Promise.allSettled(r.ok.map(async (id) => { const x = rs.find((y) => y.id === id); await st.patch("suggestions", id, { status: prev.get(id) }); x.status = prev.get(id); })); changed(); c.list.repaint(); } }); } })), { label: "Set status" }) }],
          csv: { name: "faxton-suggestions", head: ["From", "Email", "Topic", "Suggestion", "Status", "Date"], row: (x) => [x.name, x.email, x.topic, x.text, stOf(x), fmt.date(x.createdAt)] },
          drawer: (x, api) => ({ title: x.name || "Suggestion", sub: `${chipFor("suggestion", stOf(x))}<span>${esc(x.topic || "General")}</span>`, body: `<p class="ax-p" style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(x.text || "")}</p>${section("Sender", dl([["Name", esc(x.name)], ["Email", esc(x.email)], ["Sent", fmt.dateTime(x.createdAt)]]))}${section("Status", `<div class="ax-seg2">${SG.map((s) => `<button type="button" class="ax-pre" data-s="${s}" aria-pressed="${stOf(x) === s}">${s}</button>`).join("")}</div>`)}`, footer: x.email ? btn("Reply by email", { v: "primary", ic: "mail", href: `mailto:${x.email}?subject=${encodeURIComponent("Re: your suggestion to Faxton Rentals")}` }) : "", mount: (d) => $$("[data-s]", d).forEach((b) => (b.onclick = () => b.dataset.s !== stOf(x) && set(x, b.dataset.s, api))) }),
          empty: { icon: "chatlines", title: "No suggestions yet", hint: "Ideas sent from the Contact us page appear here." } });
      } };
    } });
}

// ---------- data requests (people who downloaded their own data) ----------
const DR = ["Downloaded", "Reviewed"], drSt = (x) => (x.status === "reviewed" ? "Reviewed" : "Downloaded");
export function dataRequests(ctx) {
  return pageView(ctx, { title: "Data requests", eyebrow: ctx.S.isAdmin ? "Support" : "Support console", sub: "People who confirmed it was them and downloaded a copy of their own data. Only who and when is kept here, never the data itself.", cols: ["dataRequests"], what: "data requests",
    async render({ dataRequests: items }) {
      const set = async (x, s, api) => { try { await st.patch("dataRequests", x.id, { status: s === "Reviewed" ? "reviewed" : "verified-downloaded" }); x.status = s === "Reviewed" ? "reviewed" : "verified-downloaded"; changed(); api.refresh(); toast(`Marked ${s.toLowerCase()}.`); } catch (e) { bad(e); } };
      return { html: `<div id="dr"></div>`, mount(el) {
        createList($("#dr", el), { noun: "data requests", label: "Data requests", rows: items, placeholder: "Search by name or role…", tabs: [{ k: "all", label: "All" }, ...DR.map((s) => ({ k: s, label: s, test: (x) => drSt(x) === s }))], sort: { k: "date", dir: "desc" }, search: (x) => `${x.name || ""} ${x.role || ""} ${x.uid || ""} ${x.note || ""}`,
          cols: [{ k: "from", label: "Person", role: "title", cell: (x) => `<div class="ax-id">${avatar(x.name, x.uid, 32)}<div><b>${esc(x.name || "—")}</b><small>${esc(x.role || "")}</small></div></div>` }, { k: "date", label: "Downloaded", pri: 2, sort: (x) => ms(x.at), cell: (x) => fmt.dateTime(x.at) }, { k: "note", label: "Note", pri: 3, cell: (x) => `<div class="ax-clamp" style="-webkit-line-clamp:1;max-width:260px">${esc(x.note || "")}</div>` }, { k: "status", label: "Status", role: "status", cell: (x) => `<button type="button" class="ax-chipbtn" data-cell="s" aria-haspopup="menu" aria-label="Change status, now ${esc(drSt(x))}">${chipFor("dataRequest", x.status || "verified-downloaded", drSt(x))}${I("chevD", 14)}</button>` }],
          onCell: (k, x, b, api) => menu(b, DR.map((s) => ({ label: s, checked: s === drSt(x), act: () => s !== drSt(x) && set(x, s, api) })), { align: "left", label: "Status" }),
          csv: { name: "faxton-data-requests", head: ["Person", "Role", "Downloaded", "Status", "Note"], row: (x) => [x.name, x.role, fmt.dateTime(x.at), drSt(x), x.note] },
          drawer: (x, api) => ({ title: x.name || "Data request", sub: `${chipFor("dataRequest", x.status || "verified-downloaded", drSt(x))}<span>${esc(x.role || "")}</span>`, body: `<p class="ax-p">This person confirmed it was them (email link, password or Google) and downloaded a copy of their own data on ${esc(fmt.dateTime(x.at))}. We don't keep the file or what was in it.</p>${section("Details", dl([["Name", esc(x.name || "—")], ["Role", esc(x.role || "—")], ["Account id", `<span class="num">${esc(x.uid || "")}</span>`]]))}${section("Internal note", `<textarea class="ax-input" id="drNote" rows="3" maxlength="1000" aria-label="Internal note">${esc(x.note || "")}</textarea><div style="margin-top:8px">${btn("Save note", { size: "sm", attrs: "data-drsave" })}</div>`)}${section("Status", `<div class="ax-seg2">${DR.map((s) => `<button type="button" class="ax-pre" data-s="${s}" aria-pressed="${drSt(x) === s}">${s}</button>`).join("")}</div>`)}`,
            mount: (d) => { $$("[data-s]", d).forEach((b) => (b.onclick = () => b.dataset.s !== drSt(x) && set(x, b.dataset.s, api))); $("[data-drsave]", d).onclick = async (e) => { busy(e.currentTarget, true); try { const note = $("#drNote", d).value.trim(); await st.patch("dataRequests", x.id, { note }); x.note = note; changed(); api.refresh(); toast("Note saved."); } catch (y) { bad(y); } busy(e.currentTarget, false); }; } }),
          empty: { icon: "download", title: "No data downloads yet", hint: "When someone downloads their own data from Settings, it appears here." } });
      } };
    } });
}

// ---------- user reports ----------
const RP = ["New", "Reviewing", "Action taken", "Dismissed"];
export function userReports(ctx) {
  return pageView(ctx, { title: "User reports", eyebrow: "Support", sub: "People reported by other users. Review each one and update its status.", cols: ["reports"], what: "user reports",
    async render({ reports: items }) {
      const stOf = (x) => x.status || "New", set = async (x, s, api, note) => { const prev = stOf(x), p = { status: s, ...(note ? { note } : {}) }; try { await st.patch("reports", x.id, p); Object.assign(x, p); changed(); api.refresh(); toast("Updated.", { action: "Undo", onAction: async () => { try { await st.patch("reports", x.id, { status: prev }); x.status = prev; changed(); api.refresh(); } catch (e) { bad(e); } } }); } catch (e) { bad(e); } };
      const ask = async (x, s, api) => { let note = ""; if (s === "Action taken" || s === "Dismissed") { const r = await import("./ax.js").then((m) => m.reason({ title: `Mark as ${s.toLowerCase()}`, label: "Note (optional)", placeholder: "What did you do?", helper: "Only your team sees this note.", required: false, confirmLabel: "Save", icon: "flag" })); if (r === null) return; note = r; } set(x, s, api, note); };
      const banTarget = async (x, api) => { const us = await data.safe("users"), u = us.find((y) => y.id === x.targetUid); if (!u) return toast("We couldn’t find that account.", { tone: "bad" }); if (u.id === ctx.S.user.uid || roleOf(ctx, u) === "owner" || (roleOf(ctx, u) === "admin" && !ctx.S.isOwner)) return toast("That account can’t be banned from here.", { tone: "bad" });
        if (!(await confirm({ title: `Ban ${u.name || u.email}?`, body: "They will be signed out and can’t sign back in until you unban them.", confirmLabel: "Ban user", tone: "danger", icon: "alert" }))) return; try { await st.setBanned(u.id, true); u.banned = true; toast("User banned."); } catch (e) { bad(e); } };
      return { html: `<div id="rp"></div>`, mount(el) {
        createList($("#rp", el), { noun: "reports", label: "User reports", rows: items, placeholder: "Search reports…", tabs: [{ k: "all", label: "All" }, ...RP.map((s) => ({ k: s, label: s, test: (x) => stOf(x) === s }))], sort: { k: "date", dir: "desc" }, search: (x) => `${x.targetName || ""} ${x.reporterName || ""} ${x.reason || ""} ${x.details || ""}`,
          cols: [{ k: "who", label: "Reported person", role: "title", cell: (x) => `<div class="ax-id">${avatar(x.targetName, x.targetUid, 32)}<div><b>${esc(x.targetName || "Unknown")}</b><small class="mono">${esc(String(x.targetUid || "").slice(0, 14))}</small></div></div>` }, { k: "by", label: "Reported by", pri: 2, cell: (x) => esc(x.reporterName || "—") }, { k: "why", label: "Reason", pri: 2, cell: (x) => chip("mute", x.reason || "Other") }, { k: "det", label: "Details", cell: (x) => `<div class="ax-clamp" style="-webkit-line-clamp:2;max-width:320px">${esc(x.details || "")}</div>` }, { k: "date", label: "Date", pri: 2, sort: (x) => ms(x.createdAt), cell: (x) => fmt.date(x.createdAt) }, { k: "status", label: "Status", role: "status", cell: (x) => `<button type="button" class="ax-chipbtn" data-cell="s" aria-haspopup="menu" aria-label="Change status, now ${esc(stOf(x))}">${chipFor("report", stOf(x))}${I("chevD", 14)}</button>` }],
          onCell: (k, x, b, api) => menu(b, RP.map((s) => ({ label: s, checked: s === stOf(x), act: () => s !== stOf(x) && ask(x, s, api) })), { align: "left", label: "Status" }),
          bulk: [{ label: "Set status", icon: "refresh", run: (rs, c) => menu($("[data-bulk=0]"), RP.map((s) => ({ label: s, act: async () => { const prev = new Map(rs.map((x) => [x.id, stOf(x)])); const r = await bulkRun(rs.map((x) => x.id), async (id) => { const x = rs.find((y) => y.id === id); await st.patch("reports", id, { status: s }); x.status = s; }, { label: "Updating" }); changed(); c.clear(); toast(`${r.ok.length} marked ${s.toLowerCase()}.`, { action: "Undo", onAction: async () => { await Promise.allSettled(r.ok.map(async (id) => { const x = rs.find((y) => y.id === id); await st.patch("reports", id, { status: prev.get(id) }); x.status = prev.get(id); })); changed(); c.list.repaint(); } }); } })), { label: "Set status" }) }],
          csv: { name: "faxton-user-reports", head: ["Reported", "Reported by", "Reason", "Details", "Status", "Date"], row: (x) => [x.targetName, x.reporterName, x.reason, x.details, stOf(x), fmt.date(x.createdAt)] },
          drawer: (x, api) => ({ title: x.targetName || "Report", sub: `${chipFor("report", stOf(x))}<span>${esc(x.reason || "")}</span>`, body: `${section("People", `<div class="ax-id" style="margin-bottom:10px">${avatar(x.targetName, x.targetUid, 36)}<div><b>${esc(x.targetName || "Unknown")}</b><small>Reported</small></div></div><div class="ax-id">${avatar(x.reporterName, x.reporterUid, 36)}<div><b>${esc(x.reporterName || "—")}</b><small>Reported by</small></div></div>`)}${section("Details", `<p class="ax-p" style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(x.details || "No details given.")}</p>`)}${x.note ? section("Team note", `<p class="ax-p">${esc(x.note)}</p>`) : ""}${section("Status", `<div class="ax-seg2">${RP.map((s) => `<button type="button" class="ax-pre" data-s="${s}" aria-pressed="${stOf(x) === s}">${s}</button>`).join("")}</div>`)}`,
            footer: `${x.targetUid ? btn("Open profile", { href: "#/admin/users?id=" + encodeURIComponent(x.targetUid) }) : ""}${ctx.S.isAdmin && x.targetUid ? btn("Ban user", { v: "danger", attrs: "data-ban" }) : ""}`, mount: (d) => { $$("[data-s]", d).forEach((b) => (b.onclick = () => b.dataset.s !== stOf(x) && ask(x, b.dataset.s, api))); $("[data-ban]", d)?.addEventListener("click", () => banTarget(x, api)); } }),
          empty: { icon: "flag", title: "No reports yet", hint: "When someone reports another user, it appears here." } });
      } };
    } });
}

// ---------- reports and CSV ----------
export function reports(ctx) {
  let range = "all";
  return pageView(ctx, { title: "Reports", eyebrow: "Insights", sub: "Download the platform’s data as spreadsheets that open in Excel and Google Sheets.", cols: ["applications", "viewings", "listings", "users", "tickets"], what: "reports", kpis: true,
    async render({ applications: ap, viewings: vw, listings: ls, users: us, tickets: tk }) {
      const iso = (t) => (ms(t) ? new Date(ms(t)).toISOString().slice(0, 10) : "");
      const sets = [{ k: "applications", name: "Applications", ic: "doc", docs: ap, head: ["Applicant", "Email", "Property", "Move-in", "Status", "Amount", "Submitted"], row: (a) => [a.name, a.email, a.title, a.moveIn, a.status, +a.amount || "", iso(a.createdAt)] },
        { k: "viewings", name: "Viewings", ic: "calDots", docs: vw, head: ["Renter", "Property", "Date", "Time", "Status", "Agent", "Safety alert"], row: (v) => [v.name, v.title, String(v.when || "").slice(0, 10), v.slot, v.status, v.agentName || "", v.sos ? (sosOpen(v) ? "open" : "resolved") : ""] },
        { k: "listings", name: "Listings", ic: "clipList", docs: ls, head: ["Title", "Area", "City", "Type", "Rent", "Status", "Agent", "Submitted"], row: (l) => [l.title, l.area, l.city, l.type, +l.price || "", listingState(l), l.agent?.name || "", iso(l.createdAt)] },
        { k: "users", name: "Users", ic: "users", docs: us, head: ["Name", "Email", "Role", "Country", "City", "Banned", "Joined"], row: (u) => [u.name, u.email, roleOf(ctx, u), u.country, u.city, u.banned ? "yes" : "no", iso(u.createdAt)] },
        { k: "tickets", name: "Support tickets", ic: "chatdots", docs: tk, head: ["Reference", "From", "Subject", "Status", "Priority", "Opened"], row: (t) => [t.ref, t.name, t.subject, t.status, t.priority || "Medium", iso(t.createdAt)] }];
      const RANGES = [["all", "All time"], ["30", "30 days"], ["90", "90 days"], ["365", "12 months"]];
      const rows = (s) => (range === "all" ? s.docs : s.docs.filter((d) => ms(d.createdAt) >= Date.now() - +range * DAY));
      const html = () => { const prevMs = (n) => Date.now() - 2 * n * DAY, n = range === "all" ? 30 : +range;
        return `<div class="ax-seg2" role="group" aria-label="Date range">${RANGES.map(([v, l]) => `<button type="button" class="ax-pre" data-r="${v}" aria-pressed="${range === v}">${l}</button>`).join("")}</div>
        <div class="ax-kpis scroll">${sets.map((s) => { const cur = s.docs.filter((d) => ms(d.createdAt) >= Date.now() - n * DAY).length, pr = s.docs.filter((d) => ms(d.createdAt) >= prevMs(n) && ms(d.createdAt) < Date.now() - n * DAY).length; return kpi({ label: s.name, value: fmt.num(s.docs.length), count: s.docs.length, d: pctDelta(cur, pr), vs: `last ${n} days`, icon: s.ic }); }).join("")}</div>
        <div class="ax-dcards" style="margin-top:16px">${sets.map((s) => { const r = rows(s); return `<div class="ax-card ax-dc2"><div style="display:flex;align-items:center;gap:10px"><span class="ax-tile sm">${I(s.ic, 18)}</span><b>${s.name}</b></div><div><span class="num">${fmt.num(r.length)}</span><div class="ax-sub">rows · updated just now</div></div><div class="ax-row">${btn("Download CSV", { v: "primary", size: "sm", ic: "download", attrs: `data-dl="${s.k}" ${r.length ? "" : 'disabled title="Nothing to download yet"'}` })}${btn("Preview", { size: "sm", attrs: `data-pv="${s.k}"` })}</div></div>`; }).join("")}</div>`; };
      return { html: `<div id="rpt">${html()}</div>`, mount(el) {
        const root = $("#rpt", el), paint = () => { root.innerHTML = html(); mountCharts(root); animateCounts(root); };
        root.addEventListener("click", (e) => {
          const r = e.target.closest("[data-r]"), d = e.target.closest("[data-dl]"), p = e.target.closest("[data-pv]");
          if (r) { range = r.dataset.r; paint(); }
          else if (d) { const s = sets.find((x) => x.k === d.dataset.dl); csv(`faxton-${s.k}-${AX.day()}`, s.head, rows(s).map(s.row)); toast(`${s.name} downloaded.`); }
          else if (p) { const s = sets.find((x) => x.k === p.dataset.pv), rs = rows(s).slice(0, 20); drawer.open({ title: s.name + " preview", sub: `<span>First ${rs.length} of ${rows(s).length} rows</span>`, body: rs.length ? `<div class="ax-scroll"><table class="ax-table ax-sm-table"><thead><tr>${s.head.map((h) => `<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${rs.map((x) => `<tr>${s.row(x).map((c) => `<td style="max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c ?? "")}</td>`).join("")}</tr>`).join("")}</tbody></table></div>` : empty({ icon: "doc", title: "Nothing here yet" }) }); }
        });
      } };
    } });
}

// ---------- call relay ----------
// The card lives on the Settings page for owners and admins (views.js mounts it first). /admin/calls only redirects there.
const maskUrl = (x) => { try { const u = new URL(x); return u.origin + u.pathname + (u.search ? "?" + [...u.searchParams.keys()].map((k) => k + "=••••••").join("&") : ""); } catch { return x ? "••••••••" : ""; } };
export function callsRedirect(ctx) {
  setTimeout(() => { try { history.replaceState(history.state, "", location.pathname + location.search + "#/settings?relay=1"); } catch {} ctx.render(); }, 0);
  return { title: "Settings", ...staffFlags(ctx), html: `<div class="ax-body">${AX.skeleton.card(220)}</div>` };
}
export async function mountRelayCard(host, ctx) {
  if (!host) return;
  let cfg; try { cfg = await st.getIce(); } catch { host.innerHTML = `<section class="rf-card ax-relay" id="relayCard"><div class="rf-card-h"><div><h3>Call relay</h3><p>We couldn’t load the relay settings. Check your connection and refresh the page.</p></div></div></section>`; return; }
  if (!host.isConnected) return;
  let real = { url: cfg.credsUrl || "", addr: [].concat(cfg.servers?.[0]?.urls || []).join(", "), user: cfg.servers?.[0]?.username || "", pass: cfg.servers?.[0]?.credential || "" }, revealed = false;
  const dirty = {}, on = () => !!(cfg.servers?.length || cfg.credsUrl);
  const val = (k) => (dirty[k] ? $(`#cr_${k}`, host).value.trim() : real[k]);
  const chipH = () => (on() ? chip("ok", "Your relay") : chip("mute", "Not set"));
  host.innerHTML = `<section class="rf-card ax-relay" id="relayCard" aria-labelledby="relayT"><div class="rf-card-h"><div><h3 id="relayT">Call relay</h3><p>If calls often stay on “Connecting…”, the phone or Wi-Fi is blocking direct connections and needs a relay. Create a free account at metered.ca (or Twilio, Cloudflare, Xirsys) and paste its credentials URL below. It is the easiest way.</p></div><span id="crChip" class="ax-relay-chip">${chipH()}</span></div>
    <label class="rf-fl">Credentials URL (recommended)<input id="cr_url" autocomplete="off" spellcheck="false" placeholder="https://yourapp.metered.live/api/v1/turn/credentials?apiKey=…" data-mask="url"></label>
    <p class="ax-relay-or">or enter the relay by hand:</p>
    <label class="rf-fl">Relay address(es), comma separated<input id="cr_addr" autocomplete="off" spellcheck="false" placeholder="turn:global.relay.metered.ca:80, turns:global.relay.metered.ca:443?transport=tcp"></label>
    <div class="rf-grid2"><label class="rf-fl">User name<input id="cr_user" autocomplete="off" spellcheck="false" data-mask="user"></label><label class="rf-fl">Password<input id="cr_pass" type="password" autocomplete="new-password" data-mask="pass"></label></div>
    <p class="ax-relay-rev"><button type="button" class="ax-btn" data-v="ghost" data-size="sm" id="crReveal">${I("eye", 16)}<span>Reveal saved values</span></button></p>
    <p class="ax-err" id="crE" role="alert"></p><div class="ax-relay-stat" id="crOk" role="status" aria-live="polite" hidden><span id="crSt"></span><small id="crOkT"></small></div>
    <div class="ax-set-f">${btn("Save", { v: "primary", attrs: "id=crSave" })}${btn("Save and test", { attrs: "id=crTest" })}<span class="ax-grow"></span>${btn("Remove relay", { v: "danger", attrs: `id=crX ${on() ? "" : "disabled"}` })}</div>
    <p class="ax-help" style="margin-top:14px">Signed-in users with a verified email can read these details (their apps need them to place a call), so use a relay account made for this, set a low usage limit with the provider, and change the password if it is ever misused. A credentials URL must be on metered.live, metered.ca or rtc.live.cloudflare.com.</p></section>
    <div class="ax-savebar" id="crBar" hidden><span>Unsaved changes</span>${btn("Discard", { v: "ghost", size: "sm", attrs: "id=crDisc" })}${btn("Save", { v: "primary", size: "sm", attrs: "id=crBarSave" })}</div>`;
  const el = host, inp = (k) => $(`#cr_${k}`, el), err = $("#crE", el), okB = $("#crOk", el), bar = $("#crBar", el);
  const maskVal = (k) => (!real[k] ? "" : k === "url" ? maskUrl(real.url) : k === "pass" ? "••••••••" : real.user ? real.user.slice(0, 2) + "••••••" : "");
  const paintVals = () => { ["url", "addr", "user", "pass"].forEach((k) => { if (dirty[k]) return; inp(k).value = k === "addr" ? real.addr : revealed ? real[k] : maskVal(k); inp(k).type = k === "pass" ? (revealed ? "text" : "password") : "text"; }); };
  const anyDirty = () => Object.values(dirty).some(Boolean); const flag = () => (bar.hidden = !anyDirty());
  ["url", "addr", "user", "pass"].forEach((k) => { const i = inp(k);
    i.addEventListener("focus", () => { if (!dirty[k] && i.dataset.mask && real[k] && !revealed) i.value = ""; });
    i.addEventListener("input", () => { dirty[k] = true; flag(); });
    i.addEventListener("blur", () => { if (dirty[k] && !i.value.trim() && real[k]) { dirty[k] = false; flag(); paintVals(); } }); });
  paintVals();
  ctx.S.cleanups.push(() => { bar.remove(); });
  $("#crReveal", el).onclick = (e) => { revealed = !revealed; e.currentTarget.querySelector("span").textContent = revealed ? "Hide saved values" : "Reveal saved values"; paintVals(); };
  const build = () => { err.textContent = ""; okB.hidden = true; const url = val("url"), addr = val("addr"), user = val("user"), pass = val("pass");
    if (url && !/^https:\/\//i.test(url)) { err.textContent = "The credentials URL must start with https://"; return null; }
    if (!url && !addr) { err.textContent = "Enter a credentials URL, or the relay address with user name and password."; return null; }
    const list = addr.split(",").map((x) => x.trim()).filter(Boolean);
    if (addr && !list.every((x) => /^(turns?|stuns?):/i.test(x))) { err.textContent = "Each relay address must start with turn: or turns:"; return null; }
    if (addr && list.some((x) => /^turns?:/i.test(x)) && (!user || !pass)) { err.textContent = "Enter the user name and password."; return null; }
    return { servers: addr ? [{ urls: list, username: user, credential: pass }] : [], credsUrl: url }; };
  const stat = (tone, head, sub = "") => { okB.hidden = !head; $("#crSt", el).innerHTML = head ? chip(tone, head) : ""; $("#crOkT", el).textContent = sub; };
  const save = async (test) => { const v = build(); if (!v) { stat(); return; } const btns = $$("button", el); btns.forEach((b) => (b.disabled = true)); busy($(test ? "#crTest" : "#crSave", el), true); stat();
    try { await st.saveIce(v.servers, v.credsUrl); CALLS.resetIce(); real = { url: v.credsUrl, addr: [].concat(v.servers[0]?.urls || []).join(", "), user: v.servers[0]?.username || "", pass: v.servers[0]?.credential || "" }; cfg.servers = v.servers; cfg.credsUrl = v.credsUrl; Object.keys(dirty).forEach((k) => (dirty[k] = false)); flag(); revealed = false; paintVals(); $("#crChip", el).innerHTML = chipH(); toast("Saved. New calls will use the relay."); changed();
      if (test) { stat("info", "Testing…", "Asking the relay for an address. This takes a few seconds."); const rs = await CALLS.resolveIce({ servers: v.servers, credsUrl: v.credsUrl });
        if (rs.error && !rs.servers.length) stat("bad", "Test failed", rs.error);
        else { const r = await CALLS.testRelay(rs.servers); if (r.ok) stat("ok", "Relay works", `Got a relay address in ${(r.ms / 1000).toFixed(1)}s${r.proto ? " over " + r.proto : ""}${rs.via === "url" ? " using your credentials URL" : ""}. Calls will use it when a direct connection is blocked.${rs.error ? " (The URL had a problem, so the typed address was tested: " + rs.error + ")" : ""}`); else stat("bad", "Test failed", r.why); } }
    } catch (e) { err.textContent = fe(e); stat(); }
    btns.forEach((b) => (b.disabled = false)); $("#crX", el).disabled = !on(); busy($("#crTest", el), false); busy($("#crSave", el), false); };
  $("#crSave", el).onclick = () => save(false); $("#crTest", el).onclick = () => save(true); $("#crBarSave", el).onclick = () => save(false); $("#crDisc", el).onclick = () => { Object.keys(dirty).forEach((k) => (dirty[k] = false)); flag(); paintVals(); err.textContent = ""; };
  $("#crX", el).onclick = async () => { if (!(await confirm({ title: "Remove the call relay?", body: "Calls between some networks may stay on “Connecting…” until you add a relay again.", confirmLabel: "Remove relay", tone: "danger" }))) return; try { await st.saveIce([], ""); CALLS.resetIce(); stat(); real = { url: "", addr: "", user: "", pass: "" }; cfg.servers = []; cfg.credsUrl = ""; Object.keys(dirty).forEach((k) => (dirty[k] = false)); flag(); paintVals(); $("#crChip", el).innerHTML = chipH(); $("#crX", el).disabled = true; toast("Relay removed."); changed(); } catch (e) { bad(e); } };
  if (ctx.q?.relay) requestAnimationFrame(() => { const c = $("#relayCard", el); c?.scrollIntoView({ block: "start", behavior: "smooth" }); c?.classList.add("is-flash"); setTimeout(() => c?.classList.remove("is-flash"), 1800); });
}

// ---------- add property (landlords, agencies and agents) ----------
export function addProperty(ctx, done) {
  let where = null;
  const isLandlord = ctx.S.profile?.role === "landlord";
  const amen = ["Parking", "Water supply", "Security", "Generator", "Solar / inverter", "Balcony", "Gym", "Pool", "Garden", "Wi-Fi"];
  const d = dialog({ title: "Add a property", size: "lg", icon: "home", body: `<p class="ax-p ax-muted">New listings are reviewed by the Faxton team before they go live.</p><form id="np" class="ax-form" novalidate>
    <label class="ax-field full"><span>Title</span><input class="ax-input" name="title" required maxlength="80" placeholder="3 Bedroom Apartment"></label>
    ${locFields({ style: "ax", flow: true, ids: { country: "npCountry", state: "npState", lga: "npLga" }, area: { id: "npArea", name: "area", label: "Area / neighbourhood", ph: "e.g. Lekki Phase 1" }, cityId: "npCity" })}
    <label class="ax-field"><span>Yearly rent (₦)</span><input class="ax-input" name="price" type="number" min="0" inputmode="numeric" required></label><label class="ax-field"><span>Type</span><select class="ax-input" name="type"><option>Apartment</option><option>House</option><option>Duplex</option><option>Studio</option><option>Shortlet</option></select></label>
    <label class="ax-field"><span>Bedrooms</span><input class="ax-input" name="beds" type="number" min="0" max="20" value="2" required></label><label class="ax-field"><span>Bathrooms</span><input class="ax-input" name="baths" type="number" min="1" max="20" value="2" required></label>
    <label class="ax-field"><span>Year built</span><input class="ax-input" name="yearBuilt" type="number" min="1900" max="2100" placeholder="2022"></label><label class="ax-field"><span>Parking spaces</span><input class="ax-input" name="parking" type="number" min="0" max="50" placeholder="2"></label>
    <label class="ax-field"><span>Size (m²)</span><input class="ax-input" name="sqm" type="number" min="0" placeholder="120"></label><label class="ax-field"><span>Furnishing</span><select class="ax-input" name="furnished"><option value="">Not stated</option><option>Furnished</option><option>Semi-furnished</option><option>Unfurnished</option></select></label>
    <label class="ax-field"><span>Service charge (₦ / year)</span><input class="ax-input" name="service" type="number" min="0" placeholder="350000"></label><label class="ax-field"><span>Caution deposit (₦, refundable)</span><input class="ax-input" name="deposit" type="number" min="0" placeholder="200000"></label>
    <label class="ax-field"><span>Agency fee (₦, blank is 10%)</span><input class="ax-input" name="agencyFee" type="number" min="0" placeholder="Leave blank for 10%"></label><label class="ax-field"><span>Legal fee (₦, blank is 5%)</span><input class="ax-input" name="legalFee" type="number" min="0" placeholder="Leave blank for 5%"></label>
    <div class="ax-field full"><span>Features</span><div class="ax-am">${amen.map((a) => `<label><input type="checkbox" name="am" value="${a}"> ${a}</label>`).join("")}</div></div>
    <label class="ax-field full"><span>Floor plan link (optional)</span><input class="ax-input" name="floorPlan" type="url" placeholder="https://…"></label>
    <label class="ax-field full"><span>Description</span><textarea class="ax-input" name="desc" rows="3" maxlength="800"></textarea></label>
    <div class="ax-field full"><span>Location on the map</span><div style="display:flex;align-items:center;gap:10px">${btn("Set location on map", { size: "sm", ic: "pin", attrs: "id=npLoc" })}<span class="ax-muted" id="npLocT">Not set yet</span></div></div>
    ${isLandlord ? '<label class="ax-field full"><span>Proof of ownership for this property</span><input class="ax-input" name="ownershipProof" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,application/pdf,image/jpeg,image/png,image/webp" required><small class="ax-muted">A title, deed, tax record or other accepted record for this specific property. Private to Faxton reviewers; max 10 MB.</small></label>' : ""}
    <label class="ax-field full"><span>Photo links (one per line)</span><textarea class="ax-input" name="im" rows="2" placeholder="https://…"></textarea></label><label class="ax-field full"><span>Video links (optional)</span><textarea class="ax-input" name="vd" rows="2" placeholder="https://…"></textarea></label>
    <p class="ax-err full" id="npe" role="alert"></p></form>`, footer: `${btn("Cancel", { attrs: "data-x" })}${btn("Submit for review", { v: "primary", attrs: "data-ok" })}` });
  const loc = mountLoc(d.el, { ids: { country: "npCountry", state: "npState", lga: "npLga" }, area: { id: "npArea" }, cityId: "npCity" });
  $("#npLoc", d.el).onclick = async () => { const r = await pickLocation({ lat: where?.lat, lng: where?.lng }); if (r) { where = r; $("#npLocT", d.el).textContent = `Saved (${r.lat.toFixed(4)}, ${r.lng.toFixed(4)})`; } };
  $("[data-ok]", d.el).onclick = async (e) => {
    const L = loc.commit(), fd = new FormData($("#np", d.el)), f = Object.fromEntries(fd), err = $("#npe", d.el), am = fd.getAll("am").map(String).slice(0, 12), ln = (t) => String(t || "").split("\n").map((x) => x.trim()).filter(Boolean); err.textContent = "";
    if (!f.title.trim()) return (err.textContent = "Add a title."); { const m = listingLocError(L, f.area); if (m) return (err.textContent = m); }
    const P = listingLoc(L, f.area);
    if (!(+f.price > 0)) return (err.textContent = "Enter the yearly rent in naira.");
    const im = ln(f.im), vd = ln(f.vd);
    let ownershipProof = null, ownershipMime = "";
    if (isLandlord) {
      ownershipProof = f.ownershipProof;
      const ext = String(ownershipProof?.name || "").split(".").pop().toLowerCase();
      ownershipMime = ownershipProof?.type || ({ pdf: "application/pdf", jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png", webp: "image/webp" })[ext] || "";
      if (!ownershipProof || !ownershipProof.size) return (err.textContent = "Upload proof of ownership for this property.");
      if (!["application/pdf", "image/jpeg", "image/png", "image/webp"].includes(ownershipMime)) return (err.textContent = "Use a PDF, JPEG, PNG or WebP ownership document.");
      if (ownershipProof.size > 10 * 1024 * 1024) return (err.textContent = "The ownership document must be 10 MB or smaller.");
    }
    if (im.some((u) => !/^https:\/\//.test(u)) || vd.some((u) => !/^https:\/\//.test(u))) return (err.textContent = "Photo and video links must start with https://");
    const imgs = im.slice(0, 20); if (!imgs.length) imgs.push("img/palm-court.webp");
    const u = ctx.S.user, id = f.title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 40) + "-" + Date.now().toString(36).slice(-4); busy(e.currentTarget, true);
    let ownershipDocPath = ""; const uploaded = [];
    try {
      if (isLandlord) {
        const fileName = String(ownershipProof.name || "ownership-document").normalize("NFKD").replace(/[^a-zA-Z0-9._-]+/g, "-").slice(-70) || "ownership-document";
        ownershipDocPath = "listing-verification/" + u.uid + "/" + id + "/" + Date.now() + "-" + fileName;
        await uploadBytes(storageRef(storage, ownershipDocPath), ownershipProof, { contentType: ownershipMime, customMetadata: { ownerUid: u.uid, documentType: "listing-ownership", listingId: id } });
        uploaded.push(ownershipDocPath);
      }
      await st.createListing({ id, title: f.title.trim(), ...(ownershipDocPath ? { ownershipDocPath } : {}), ...P, price: +f.price, beds: +f.beds, baths: +f.baths, sqm: +f.sqm || 0, type: f.type, yearBuilt: +f.yearBuilt || "", parking: f.parking === "" ? "" : +f.parking, furnished: f.furnished || "", floorPlan: /^https:\/\//.test(f.floorPlan || "") ? f.floorPlan : "", desc: f.desc.trim(), status: "pending", service: +f.service || 0, deposit: +f.deposit || 0, ...(f.agencyFee !== "" ? { agencyFee: +f.agencyFee } : {}), ...(f.legalFee !== "" ? { legalFee: +f.legalFee } : {}), lat: where?.lat ?? 6.45, lng: where?.lng ?? 3.47, hasPin: !!where, images: imgs, thumb: imgs[0], videos: vd.slice(0, 6), amenities: am, ownerUid: u.uid, agent: { id: u.uid, name: u.displayName || ctx.S.profile?.name || "Faxton owner", avatar: ctx.S.profile?.photo || "img/av-daniel.webp", photo: ctx.S.profile?.photo || "img/av-daniel.webp" } });
      data.invalidate("listings"); d.close(); toast("Property submitted for review."); done?.();
    } catch (x) { await Promise.all(uploaded.map((path) => deleteObject(storageRef(storage, path)).catch(() => {}))); err.textContent = fe(x); busy(e.currentTarget, false); }
  };
}

// ---------- shared pieces for the portals ----------
const verifyBanner = (ctx, needs, vst, agency) => (needs ? `<div class="ax-banner" data-t="${vst === "rejected" ? "bad" : "warn"}" data-t2="verify" data-tour="verify">${I(vst === "rejected" ? "info" : "clock", 20)}<div><b>${vst === "rejected" ? "We couldn’t verify your account" : "Your account is being verified"}</b><p>${vst === "rejected" ? esc(ctx.S.profile?.verification?.reason || "Please contact support for details.") : `This usually takes about ${agency ? "3 to 5 minutes" : "10 minutes"}. We’ll notify you the moment you’re verified, and then you can start listing properties.`}</p></div></div>` : "");
function locHandler(ctx, ls, root) { $$("[data-loc]", root).forEach((b) => (b.onclick = async () => { const l = ls.find((x) => x.id === b.dataset.loc); const r = await pickLocation({ lat: l.hasPin ? l.lat : undefined, lng: l.hasPin ? l.lng : undefined, title: `Location of ${l.title}` }); if (!r) return; try { await st.patch("listings", l.id, { lat: r.lat, lng: r.lng, hasPin: true }); Object.assign(l, { lat: r.lat, lng: r.lng, hasPin: true }); toast("Location saved. It now shows on the map."); b.querySelector("span").textContent = "Edit location"; } catch (e) { bad(e); } })); }
const VSTAT = ["Requested", "Confirmed", "Completed", "Cancelled"];
function viewReqTable(rows, empty0) {
  return rows.length ? `<div class="ax-scroll"><table class="ax-table ax-sm-table" aria-label="Viewing requests"><thead><tr><th>Prospect</th><th>When</th><th>Status</th><th class="al-right"></th></tr></thead><tbody>${rows.map((v) => `<tr data-id="${esc(v.id)}"><td data-role="title" data-label="Prospect"><div class="ax-id">${avatar(v.name, v.uid, 28)}<div><b>${esc(v.name || "")}</b><small>${esc(v.title || "")}</small></div></div></td><td data-label="When">${esc(fmt.day(v.when))}${v.slot ? `, ${esc(v.slot)}` : ""}</td><td data-role="status" data-label="Status"><button type="button" class="ax-chipbtn" data-vs="${esc(v.id)}" aria-haspopup="menu">${sosOpen(v) ? chipFor("sos", "open") : chipFor("viewing", v.status)}${I("chevD", 14)}</button></td><td data-role="actions" class="al-right">${v.status === "Requested" ? `<div class="ax-ra" style="justify-content:flex-end">${btn("Confirm", { v: "soft", size: "sm", attrs: `data-vc="${esc(v.id)}"` })}</div>` : ""}</td></tr>`).join("")}</tbody></table></div>` : empty0;
}
function wireViews(root, vws, rerender) {
  const set = async (v, s) => { try { await st.setStatus("viewings", v.id, s); v.status = s; changed(); toast("Status updated."); rerender(); } catch (e) { bad(e); } };
  $$("[data-vs]", root).forEach((b) => (b.onclick = () => { const v = vws.find((x) => x.id === b.dataset.vs); menu(b, VSTAT.map((s) => ({ label: s, checked: s === v.status, act: () => s !== v.status && set(v, s) })), { align: "left", label: "Status" }); }));
  $$("[data-vc]", root).forEach((b) => (b.onclick = () => set(vws.find((x) => x.id === b.dataset.vc), "Confirmed")));
}

// ---------- property owner and agency dashboard ----------
function portfolio(ctx, { ls, apps, views, offers, maint }, kind) {
  const agency = kind === "agency", prof = ctx.S.profile || {}, needsV = !prof.verified, vst = prof.verification?.status || "pending", bs = buckets("365"), L = bs.length - 1;
  const live = ls.filter(isActive), pend = ls.filter(isPendingL), tenants = apps.filter(approved), occupied = new Set([...tenants.map((a) => a.listingId), ...ls.filter((l) => l.available === false).map((l) => l.id)]);
  const occ = ls.length ? Math.round((occupied.size / ls.length) * 100) : 0, roll = ls.filter((l) => occupied.has(l.id)).reduce((s, l) => s + (+l.price || 0), 0), enq = [...apps, ...views], perL = (id) => enq.filter((x) => x.listingId === id).length;
  const bm = buckets("90"), eS = per(enq, bm), pv = views.filter((v) => v.status === "Requested"), open = offers.filter((o) => !["Accepted", "Declined", "Withdrawn"].includes(o.status) && o.turn === "owner");
  const props = ls.map((l) => `<tr data-id="${esc(l.id)}"><td data-role="title" data-label="Property"><div class="ax-id">${thumb(thumbOf(l), 32)}<div><b>${esc(l.title)}</b><small>${esc([l.area, l.city].filter(Boolean).join(", "))}</small></div></div></td><td data-label="Rent" class="al-right"><span class="ax-money">${naira(l.price)}</span></td><td data-label="Enquiries" class="al-right num">${perL(l.id)}</td><td data-role="status" data-label="Status">${isPendingL(l) ? chipFor("listing", "pending") : l.archived ? chipFor("listing", "archived") : occupied.has(l.id) ? chipFor("listing", "occupied") : chipFor("listing", "available")}</td><td data-role="actions" class="al-right"><div class="ax-ra" style="justify-content:flex-end">${isActive(l) ? btn("View", { size: "sm", href: "#/home/" + encodeURIComponent(l.id) }) : ""}${btn(l.hasPin ? "Edit location" : "Set location", { size: "sm", ic: "pin", attrs: `data-loc="${esc(l.id)}"` })}</div></td></tr>`);
  const recent = [...apps].sort((a, b) => ms(b.createdAt) - ms(a.createdAt)).slice(0, 5);
  const html = `${verifyBanner(ctx, needsV, vst, true)}<div class="ax-attns" style="grid-template-columns:repeat(4,minmax(0,1fr))" data-t="att">${attn({ label: "Applications to review", count: apps.filter((a) => /review/i.test(a.status || "")).length, href: kind === "agency" ? "/agency" : "/portfolio", icon: "doc" })}${attn({ label: "Viewing requests", count: pv.length, href: "/portfolio", icon: "calDots" })}${attn({ label: "Maintenance requests", count: maint.filter((m) => m.status === "Open").length, href: "/tenants/maintenance", icon: "tool" })}${attn({ label: "Offers awaiting your reply", count: open.length, href: "/offers", icon: "tag" })}</div>
    <div class="ax-kpis scroll" data-t="kpis">${kpi({ label: agency ? "Active listings" : "Total listings", value: fmt.num(agency ? live.length : ls.length), count: agency ? live.length : ls.length, sub: `${pend.length} awaiting review`, icon: "home" })}${kpi({ label: "Active tenants", value: fmt.num(tenants.length), count: tenants.length, sub: `${apps.filter((a) => /review/i.test(a.status || "")).length} applications to review`, icon: "users" })}${kpi({ label: "Annual rent roll", value: fmt.nairaC(roll), title: roll ? naira(roll) : "", sub: "from occupied properties", icon: "wallet" })}${kpi({ label: "Occupancy rate", value: occ + "%", sub: `${occupied.size} of ${ls.length} properties`, icon: "chart" })}</div>
    <div class="ax-grid"><div class="ax-c8" data-t="pipe">${card("Enquiries", "Viewing requests and applications each week", barChart([{ name: "Enquiries", data: eS }], bm.map((x) => x.label)))}</div><div class="ax-c4">${card("Occupancy", "Occupied and vacant properties", donut([["Occupied", occupied.size], ["Vacant", Math.max(0, ls.length - occupied.size)]].filter((x) => x[1] > 0), { value: occ + "%", label: "Occupied" }))}</div></div>
    <div class="ax-grid"><div class="ax-c8" data-t="props">${card("Your properties", `${ls.length} propert${ls.length === 1 ? "y" : "ies"}`, miniTable([["Property"], ["Rent / yr", "al-right"], ["Enquiries", "al-right"], ["Status"], [""]], props, empty({ icon: "home", title: "You haven’t added a property yet.", hint: "Choose Add property to get started.", action: btn("Add property", { v: "primary", ic: "plus", attrs: "data-add" }) })), { pad: false })}</div><div class="ax-c4">${card("Recent applications", "Latest people who applied", recent.length ? `<ul class="ax-chats">${recent.map((a) => `<li>${avatar(a.name, a.uid, 32)}<div><b>${esc(a.name || "Applicant")}</b><small>${esc(a.title || "")}</small></div>${chipFor("application", a.status || "Under review")}</li>`).join("")}</ul>` : empty({ icon: "doc", title: "No applications yet" }), { pad: false })}</div></div>
    <div class="ax-grid"><div class="ax-c12" data-t="views">${card("Viewing requests", "Confirm or decline requests", viewReqTable([...views].sort((a, b) => ms(b.createdAt) - ms(a.createdAt)).slice(0, 8), empty({ icon: "calDots", title: "No viewing requests yet", hint: "When someone asks to view a home, it appears here." })), { pad: false })}</div></div>`;
  return { html, mount(root) {
    locHandler(ctx, ls, root); wireViews(root, views, () => { const hv = $('[data-t="views"]', root); hv.outerHTML = `<div class="ax-c12" data-t="views">${card("Viewing requests", "Confirm or decline requests", viewReqTable([...views].sort((a, b) => ms(b.createdAt) - ms(a.createdAt)).slice(0, 8), ""), { pad: false })}</div>`; wireViews(root, views, () => ctx.render()); });
  } };
}

// ---------- agent desk ----------
const leadsOf = (apps, views) => [...views.map((v) => ({ id: v.id, kind: "viewing", name: v.name || "Prospect", email: "", prop: v.title, listingId: v.listingId, src: "Viewing request", stage: v.status === "Confirmed" ? "Viewing scheduled" : v.status === "Completed" ? "Viewed" : /cancel/i.test(v.status || "") ? "Declined" : "New lead", createdAt: v.createdAt })), ...apps.map((a) => ({ id: a.id, kind: "application", name: a.name || "Applicant", email: a.email, prop: a.title, listingId: a.listingId, src: "Application", stage: approved(a) ? "Closed" : /reject|cancel|declin/i.test(a.status || "") ? "Declined" : "Application", createdAt: a.createdAt }))].sort((x, y) => ms(y.createdAt) - ms(x.createdAt));
const todayKey = () => new Date().toISOString().slice(0, 10);
function agentDash(ctx, { ls, apps, views, offers }, sub) {
  const prof = ctx.S.profile || {}, needsV = !prof.verified, vst = prof.verification?.status || "pending", leads = leadsOf(apps, views), live = ls.filter(isActive), closed = apps.filter(approved), booked = views.filter((v) => /confirmed|completed/i.test(v.status || ""));
  const bm = buckets("365"), conv = leads.length ? Math.round((closed.length / leads.length) * 1000) / 10 : 0, perL = (id) => ({ e: [...apps, ...views].filter((x) => x.listingId === id).length, v: views.filter((x) => x.listingId === id).length });
  const stages = ["New lead", "Viewing scheduled", "Application", "Closed", "Declined"], cnt = (s) => leads.filter((x) => x.stage === s || (s === "Viewing scheduled" && x.stage === "Viewed")).length;
  const leadRow = (x) => `<tr><td data-role="title" data-label="Name"><div class="ax-id">${avatar(x.name, x.id, 28)}<div><b>${esc(x.name)}</b><small>${esc(x.email || "")}</small></div></div></td><td data-label="Property interest">${esc(x.prop || "—")}</td><td data-label="Source" data-priority="2">${esc(x.src)}</td><td data-role="status" data-label="Stage">${chipFor("lead", x.stage)}</td><td data-label="Last contact" data-priority="2">${fmt.rel(x.createdAt)}</td></tr>`;
  const leadTbl = (rows) => miniTable([["Name"], ["Property interest"], ["Source"], ["Stage"], ["Last contact"]], rows.map(leadRow), empty({ icon: "users", title: "No leads yet", hint: "They appear when someone books a viewing or applies." }));
  const add = needsV ? "" : "";
  let body, title = "Overview";
  if (sub === "leads") { title = "Leads"; body = `<div class="ax-pipe">${stages.map((s) => `<div><b>${cnt(s)}</b><span>${s}</span></div>`).join("")}</div>${card("All leads", "Newest first", leadTbl(leads), { pad: false })}`; }
  else if (sub === "clients") { title = "Clients"; const seen = new Map(); leads.forEach((x) => { const k = (x.email || x.name).toLowerCase(); if (!seen.has(k)) seen.set(k, { ...x, n: 0 }); seen.get(k).n++; }); body = card("Everyone you’re working with", `${seen.size} client${seen.size === 1 ? "" : "s"}`, miniTable([["Client"], ["Email"], ["Latest interest"], ["Enquiries", "al-right"], ["Stage"]], [...seen.values()].map((x) => `<tr><td data-role="title" data-label="Client"><div class="ax-id">${avatar(x.name, x.id, 28)}<b>${esc(x.name)}</b></div></td><td data-label="Email">${esc(x.email || "—")}</td><td data-label="Interest">${esc(x.prop || "—")}</td><td class="al-right num" data-label="Enquiries">${x.n}</td><td data-role="status" data-label="Stage">${chipFor("lead", x.stage)}</td></tr>`), empty({ icon: "user", title: "No clients yet" })), { pad: false }); }
  else if (sub === "viewings") { title = "Viewings"; body = card("Respond to viewing requests", `${views.length} request${views.length === 1 ? "" : "s"}`, viewReqTable([...views].sort((a, b) => ms(b.createdAt) - ms(a.createdAt)), empty({ icon: "calDots", title: "No viewing requests yet" })), { pad: false, tag: "views" }); }
  else if (sub === "listings") { title = "Listings"; body = card("Your listings", `${ls.length} propert${ls.length === 1 ? "y" : "ies"}`, miniTable([["Property"], ["Rent / yr", "al-right"], ["Enquiries", "al-right"], ["Status"], [""]], ls.map((l) => `<tr><td data-role="title" data-label="Property"><div class="ax-id">${thumb(thumbOf(l), 32)}<div><b>${esc(l.title)}</b><small>${esc([l.area, l.city].filter(Boolean).join(", "))}</small></div></div></td><td class="al-right" data-label="Rent"><span class="ax-money">${naira(l.price)}</span></td><td class="al-right num" data-label="Enquiries">${perL(l.id).e}</td><td data-role="status" data-label="Status">${chipFor("listing", listingState(l) === "active" ? "available" : listingState(l))}</td><td data-role="actions" class="al-right"><div class="ax-ra" style="justify-content:flex-end">${isActive(l) ? btn("View", { size: "sm", href: "#/home/" + encodeURIComponent(l.id) }) : ""}${btn(l.hasPin ? "Edit location" : "Set location", { size: "sm", ic: "pin", attrs: `data-loc="${esc(l.id)}"` })}</div></td></tr>`), empty({ icon: "home", title: "You haven’t added a property yet." })), { pad: false, tag: "props" }); }
  else {
    const tasks = [...views.filter((v) => v.status === "Requested").slice(0, 3).map((v) => ({ ic: "phone", t: `Respond to ${v.name || "a prospect"}`, d: `Viewing request: ${v.title || ""}`, w: v.slot || "Today", href: "/agent-dashboard/viewings" })), ...views.filter((v) => v.status === "Confirmed" && String(v.when).slice(0, 10) === todayKey()).slice(0, 2).map((v) => ({ ic: "calDots", t: `Viewing with ${v.name || "a prospect"}`, d: v.title || "", w: v.slot || "Today", href: "/agent-dashboard/viewings" })), ...apps.filter((a) => /review/i.test(a.status || "")).slice(0, 3).map((a) => ({ ic: "doc", t: `Review ${a.name || "an applicant"}’s application`, d: a.title || "", w: "Today", href: "/agent-dashboard/leads" }))].slice(0, 5);
    let done = {}; try { done = JSON.parse(localStorage.getItem("tasks_" + ctx.S.user.uid + "_" + todayKey()) || "{}"); } catch {}
    const upcoming = views.filter((v) => !/cancel|completed/i.test(v.status || "")).sort((a, b) => String(a.when).localeCompare(String(b.when))).slice(0, 5);
    body = `<div class="ax-kpis scroll" data-t="kpis">${kpi({ label: "Total leads", value: fmt.num(leads.length), count: leads.length, d: pctDelta(within(leads, Date.now() - 30 * DAY, Date.now()), within(leads, Date.now() - 60 * DAY, Date.now() - 30 * DAY)), vs: "vs previous 30 days", icon: "users", href: "/agent-dashboard/leads" })}${kpi({ label: "Active listings", value: fmt.num(live.length), count: live.length, sub: `${ls.length - live.length} not live yet`, icon: "home", href: "/agent-dashboard/listings" })}${kpi({ label: "Booked viewings", value: fmt.num(booked.length), count: booked.length, sub: `${views.filter((v) => v.status === "Requested").length} waiting for you`, icon: "calDots", href: "/agent-dashboard/viewings" })}${kpi({ label: "Conversion", value: conv + "%", sub: "closed deals out of leads", icon: "chart" })}</div>
    <div class="ax-pipe" style="margin-top:16px" data-t="pipe">${stages.map((s) => `<div><b>${cnt(s)}</b><span>${s}</span></div>`).join("")}</div>
    <div class="ax-grid"><div class="ax-c8">${card("Recent leads", "", leadTbl(leads.slice(0, 6)), { right: `<a class="ax-link" href="#/agent-dashboard/leads">View all</a>`, pad: false })}</div><div class="ax-c4">${card("Follow-ups for today", "", tasks.length ? `<ul class="ax-chats">${tasks.map((t, i) => `<li><label class="ax-check"><input type="checkbox" data-task="${i}-${esc(t.t)}" ${done[i + "-" + t.t] ? "checked" : ""} aria-label="Done"></label><span class="ax-tile sm">${I(t.ic, 16)}</span><div><b>${esc(t.t)}</b><small>${esc(t.d)}</small></div></li>`).join("")}</ul>` : empty({ icon: "checkc", title: "You’re all caught up." }), { pad: false })}</div></div>
    <div class="ax-grid"><div class="ax-c6" data-t="views">${card("Upcoming viewings", "", viewReqTable(upcoming, empty({ icon: "calDots", title: "No upcoming viewings" })), { right: `<a class="ax-link" href="#/agent-dashboard/viewings">View all</a>`, pad: false })}</div><div class="ax-c6" data-t="props">${card("Top listings", "By enquiries", [...ls].sort((a, b) => perL(b.id).e - perL(a.id).e).slice(0, 4).map((l) => `<div class="ax-id" style="padding:10px 16px;border-top:1px solid var(--ax-border)">${thumb(thumbOf(l), 40)}<div style="flex:1"><b>${esc(l.title)}</b><small>${esc(l.area || "")} · ${naira(l.price)}</small></div><span class="num ax-muted">${perL(l.id).e} enquiries</span></div>`).join("") || empty({ icon: "home", title: "Add a property to see it here." }), { pad: false })}</div></div>`;
  }
  return { title, html: `${verifyBanner(ctx, needsV, vst, false)}${body}`, mount(root) {
    locHandler(ctx, ls, root); wireViews(root, views, () => ctx.render());
    $$("[data-task]", root).forEach((c) => (c.onchange = () => { try { const k = "tasks_" + ctx.S.user.uid + "_" + todayKey(), o = JSON.parse(localStorage.getItem(k) || "{}"); o[c.dataset.task] = c.checked; localStorage.setItem(k, JSON.stringify(o)); } catch {} }));
  } };
}

export async function ownerPage(ctx, kind, sub = "") {
  if (!allowed(ctx, kind)) return denied(ctx);
  const TITLE = { landlord: "Dashboard", agency: "Dashboard", agent: { leads: "Leads", clients: "Clients", viewings: "Viewings", listings: "Listings", "": "Overview" }[sub] || "Overview" }[kind] || "Dashboard";
  const eyebrow = { landlord: "Owner portal", agency: "Agency portal", agent: "Agent portal" }[kind], u = ctx.S.user.uid, prof = ctx.S.profile || {};
  const needsV = !prof.verified, name = AX.first(prof.name || ctx.S.user.displayName);
  const subt = { landlord: "Here’s what’s happening with your properties.", agency: "Here’s your team’s performance and business overview.", agent: "Your listings, leads and viewings at a glance." }[kind];
  const addBtn = btn("Add property", { v: "primary", ic: "plus", attrs: `id="addp" ${needsV ? 'aria-disabled="true" title="Available once your account is verified"' : ""}` });
  const v = pageView(ctx, { title: kind === "agent" && sub ? TITLE : "Dashboard", eyebrow, sub: kind === "agent" && sub ? "" : `${name ? "Welcome back, " + name + ". " : ""}${subt}`, actions: addBtn, kpis: true, what: "your dashboard", role: kind,
    cols: [["ls", () => data.safe("listings", { uid: u })], ["apps", () => data.safe("applications", { uid: u })], ["views", () => data.safe("viewings", { uid: u })], ["offers", () => data.safe("offers", { uid: u })], ["maint", () => data.safe("maintenance", { uid: u })]],
    async render({ ls, apps, views, offers, maint }, { root }) {
      const r = kind === "agent" ? agentDash(ctx, { ls, apps, views, offers }, sub) : portfolio(ctx, { ls, apps, views, offers, maint }, kind);
      return { html: r.html, mount(el) {
        r.mount?.(el); const open = () => (needsV ? toast("Your account is still being verified. You’ll be able to list properties as soon as it’s done.") : addProperty(ctx, () => ctx.render()));
        $("#addp", root).onclick = open; el.querySelectorAll("[data-add]").forEach((b) => (b.onclick = open));
        if (hq().q.new) { setQ({ new: "" }); open(); }
      } };
    } });
  return { ...v, role: kind, admin: undefined };
}

// ---------- support dashboard ----------
async function supportDash(ctx) {
  return pageView(ctx, { title: "Dashboard", eyebrow: "Support console", sub: "Handle customer issues quickly and keep the queue short.", kpis: true, what: "the support dashboard", actions: `${btn("Open ticket queue", { v: "primary", ic: "chatdots", href: "#/support/tickets" })}${btn("Help centre", { ic: "help", href: "#/help" })}`,
    cols: ["tickets", ["convs", () => data.safe("conversations")]],
    async render({ tickets: tks, convs }) {
      const bs = buckets("365"), now = Date.now(), open = tks.filter((t) => groupOf(t) === "Open"), prog = tks.filter((t) => groupOf(t) === "In progress"), done = tks.filter(isRes), liveT = tks.filter((t) => !isRes(t)), overdue = liveT.filter((t) => ms(t.createdAt) && now - ms(t.createdAt) > 48 * 36e5);
      const wk = tks.filter((t) => now - ms(t.createdAt) < 7 * DAY).length, pw = tks.filter((t) => { const a = now - ms(t.createdAt); return a >= 7 * DAY && a < 14 * DAY; }).length, unread = convs.filter((c) => c.unread).length;
      const cats = {}; tks.forEach((t) => { cats[t.subject || "Other"] = (cats[t.subject || "Other"] || 0) + 1; });
      const queue = [...liveT].sort((a, b) => ms(a.createdAt) - ms(b.createdAt)).slice(0, 6), chats = [...convs].sort((a, b) => ms(b.lastAt) - ms(a.lastAt)).slice(0, 5);
      const row = (t) => `<tr data-id="${esc(t.id)}" data-go="/support/tickets?id=${esc(t.id)}" style="cursor:pointer"><td data-label="#" class="num">#${esc(t.ref || "")}</td><td data-role="title" data-label="Customer"><div class="ax-id">${avatar(t.name, t.uid, 28)}<b>${esc(t.name || "Customer")}</b></div></td><td data-label="Issue">${esc(t.subject || "")}</td><td data-label="Priority">${overdue.includes(t) ? chipFor("priority", "overdue") : chipFor("priority", t.priority || "medium")}</td><td data-role="status" data-label="Status">${chipFor("ticket", groupOf(t))}</td><td data-label="Opened">${fmt.rel(t.createdAt)}</td></tr>`;
      return { html: `<div class="ax-attns" style="grid-template-columns:repeat(4,minmax(0,1fr))" data-t="att">${attn({ label: "Open tickets", count: open.length, href: "/support/tickets", icon: "chatdots" })}${attn({ label: "In progress", count: prog.length, href: "/support/tickets?tab=In progress", icon: "clock" })}${attn({ label: "Overdue (48h+)", count: overdue.length, href: "/support/tickets", icon: "flag" })}${attn({ label: "Chats with new messages", count: unread, href: "/messages", icon: "msg" })}</div>
        <div class="ax-kpis scroll" data-t="kpis">${kpi({ label: "Open tickets", value: fmt.num(open.length), count: open.length, sub: `${liveT.length} still unresolved`, icon: "chatdots", href: "/support/tickets" })}${kpi({ label: "In progress", value: fmt.num(prog.length), count: prog.length, sub: "being handled now", icon: "clock" })}${kpi({ label: "Resolved", value: fmt.num(done.length), count: done.length, sub: `${tks.length ? Math.round((done.length / tks.length) * 100) : 0}% of all tickets`, icon: "check" })}${kpi({ label: "New this week", value: fmt.num(wk), count: wk, d: pctDelta(wk, pw), vs: "vs last week", icon: "trend" })}</div>
        <div class="ax-grid"><div class="ax-c8" data-t="queue">${card("Ticket queue", "Oldest unresolved tickets first", miniTable([["#"], ["Customer"], ["Issue"], ["Priority"], ["Status"], ["Opened"]], queue.map(row), empty({ icon: "checkc", title: "No unresolved tickets. Nice work." })), { right: `<a class="ax-link" href="#/support/tickets">Open queue</a>`, pad: false })}</div><div class="ax-c4" data-t="chats">${card("Live conversations", `${convs.length} conversation${convs.length === 1 ? "" : "s"}`, chats.length ? `<ul class="ax-chats">${chats.map((c) => `<li>${avatar(c.userName, c.uid, 32)}<div><b>${esc(c.userName || "Customer")}</b><small>${esc(c.last || c.listingTitle || "")}</small></div><span class="ax-muted" style="font-size:12px">${fmt.rel(c.lastAt)}</span>${c.unread ? '<i class="ax-dot" title="New message"></i>' : ""}</li>`).join("")}</ul>` : empty({ icon: "chatdots", title: "No conversations yet" }), { pad: false })}</div></div>
        <div class="ax-grid ax-lazy"><div class="ax-c4">${card("Support volume", "Received and resolved", barChart([{ name: "Received", data: per(tks, bs) }, { name: "Resolved", data: per(done, bs) }], bs.map((x) => x.label), { h: 180 }))}</div><div class="ax-c4">${card("Ticket categories", "By issue type", donut(Object.entries(cats).sort((a, b) => b[1] - a[1]).slice(0, 5), { value: tks.length, label: "Total tickets" }))}</div><div class="ax-c4">${card("Recent escalations", "Waiting more than 48 hours", miniTable([["#"], ["Customer"], ["Waiting"]], overdue.slice(0, 5).map((t) => `<tr data-go="/support/tickets?id=${esc(t.id)}" style="cursor:pointer"><td class="num" data-label="#">#${esc(t.ref || "")}</td><td data-label="Customer">${esc(t.name || "")}</td><td data-label="Waiting">${fmt.age(t.createdAt)}</td></tr>`), empty({ icon: "checkc", title: "Nothing is overdue." })), { pad: false })}</div></div>`,
        mount(el) { $$("[data-go]", el).forEach((r) => (r.onclick = () => ctx.go("#" + r.dataset.go))); } };
    } });
}
export async function supportPage(ctx, sub) {
  if (!allowed(ctx, "support")) return denied(ctx);
  const v = sub === "suggestions" ? suggestions(ctx) : sub === "data-requests" ? dataRequests(ctx) : sub === "services" ? await (await import("./admin2.js")).serviceRequests(ctx) : sub === "tickets" ? await (await import("./ax-sections.js")).ticketCenter(ctx) : await supportDash(ctx);
  return { ...v, role: "support", admin: undefined };
}
